// Human feedback is local mock state, independent of AI role settings.
let focusWriting=false,contextTab='ai',humanFilter='Comments',selectedComment=null,replyTarget=null;
const humanSettings={markers:true,previews:false,notifications:'Mentions only',resolved:false};
const comments=[
{id:'opening',anchor:'At eight in the morning',author:'Maya Chen',role:'Editor',text:'Could we name the river or neighbourhood to ground this opening scene?',type:'Comments',replies:[],resolved:false,task:false},
{id:'figures',anchor:'Cycling in the city increased',author:'Jonas Weber',role:'Research editor',text:'Let’s discuss whether the 24% figure should be attributed to the transport office in this passage.',type:'Discussions',replies:[{author:'Maya Chen',text:'Agreed. Keep the counting method visible when we discuss the wording.'}],resolved:false,task:false},
{id:'residents',anchor:'For residents, the discussion',author:'Elena Ruiz',role:'Reporter',text:'Add a resident’s interview to support the everyday experience described here.',type:'Comments',replies:[],resolved:false,task:false}
];
function persistHuman(){save('authoria-human',JSON.stringify({settings:humanSettings,comments}))}
try{const d=JSON.parse(read('authoria-human')||'null');if(d){for(const k of ['markers','previews','resolved'])if(typeof d.settings?.[k]==='boolean')humanSettings[k]=d.settings[k];if(['Mentions only','All activity','Off'].includes(d.settings?.notifications))humanSettings.notifications=d.settings.notifications;for(const c of comments){const prev=d.comments?.find(x=>x.id===c.id);if(prev){c.resolved=!!prev.resolved;c.task=!!prev.task;c.replies=Array.isArray(prev.replies)?prev.replies.filter(r=>typeof r.author==='string'&&typeof r.text==='string'):[];}}}}catch{}
const originalAnnotate=annotate;
annotate=function(){originalAnnotate();if(focusWriting){for(const k of Object.keys(team))$('#article').classList.remove('show-'+k);$('#article').querySelectorAll('.claim,[data-evidence]').forEach(n=>{n.classList.remove('selected');n.removeAttribute('title')});}};
// Focus prevents annotation interactions but retains every saved role preference.
$('#article').addEventListener('click',e=>{if(focusWriting){e.stopImmediatePropagation();}},true);
function groupEvidence(){if(state==='default')return;const panel=$('#panel');if(panel.querySelector('.evidence-group'))return;const start=panel.querySelector('.evidence-status');if(!start)return;const end=[...panel.querySelectorAll('.section-title')].find(n=>n.textContent.startsWith('AI perspectives'));const box=document.createElement('section');box.className='evidence-group';box.setAttribute('aria-label','Evidence');start.before(box);box.innerHTML='<div class="label">Evidence <span>Connected source material</span></div>';let n=start;while(n&&n!==end){const next=n.nextSibling;box.appendChild(n);n=next;}}
function setTab(t){contextTab=t;$('#panel').hidden=t!=='ai';$('#human-panel').hidden=t!=='human';$('#ai-tab').setAttribute('aria-selected',t==='ai');$('#collaboration-tab').setAttribute('aria-selected',t==='human');$('.context-footer').innerHTML=t==='ai'?'<span>✧</span> AI offers perspective. You make the call.':'Human feedback · mock collaboration · stored locally';if(t==='human')renderHuman();}
const renderInsights=render;
render=function(next='default',claim=activeClaim){selectedComment=null;replyTarget=null;renderInsights(next,claim);groupEvidence();setTab('ai');refreshComments();};
$('#ai-tab').onclick=()=>setTab('ai');$('#collaboration-tab').onclick=()=>{setTab('human');openMobile()};
// Existing AI navigation always reveals its own tab.
document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>setTab('ai')));
$('#context-toggle').addEventListener('click',()=>{if(contextTab==='human')renderHuman()});
function passage(c){return [...$('#article').querySelectorAll('p')].find(p=>!p.closest('[data-human-preview]')&&p.textContent.includes(c.anchor));}
function replyForm(c){return `<form class="human-reply" data-reply-form="${c.id}"><label>Reply to ${esc(c.author)}<textarea required maxlength="1000" name="reply" placeholder="Add a reply…"></textarea></label><button type="submit">Save reply locally</button><button type="button" data-human="cancel-reply" data-id="${c.id}">Cancel</button></form>`}
function humanActions(c,preview=false){return `<div class="human-actions"><button data-human="reply" data-id="${c.id}">Reply</button>${preview?`<button data-human="thread" data-id="${c.id}">Open thread ↗</button>`:`<button data-human="task" data-id="${c.id}" ${c.task?'disabled':''}>${c.task?'Task created':'Create task'}</button><button data-human="resolve" data-id="${c.id}">${c.resolved?'Reopen':'Resolve'}</button>`}</div>`}
function card(c){const p=passage(c);return `<section class="human-card ${selectedComment===c.id?'thread-selected':''}" id="thread-${c.id}"><div class="human-author"><strong>${esc(c.author)}</strong><small>${esc(c.role)} · ${c.resolved?'Resolved':c.type==='Discussions'?'Discussion':'Comment'}</small></div><button class="passage-link" data-human="passage" data-id="${c.id}">${p?'↗ '+esc(c.anchor)+'…':'Passage unavailable after editing'}</button><p>${esc(c.text)}</p>${c.task?'<div class="task-label">□ To-do · '+esc(c.text)+'</div>':''}${c.replies.map(r=>`<div class="human-reply-saved"><strong>${esc(r.author)}</strong><p>${esc(r.text)}</p></div>`).join('')}${humanActions(c)}${replyTarget===c.id?replyForm(c):''}</section>`}
function renderHuman(){const shown=comments.filter(c=>humanFilter==='Resolved'?c.resolved:(!c.resolved||humanSettings.resolved)&&(humanFilter==='To-do'?c.task:humanFilter==='Discussions'?c.type==='Discussions'||c.replies.length:c.type==='Comments'));$('#human-panel').innerHTML=`<div class="label">Human feedback <span>Mock team</span></div><div class="human-filters" role="group" aria-label="Collaboration filters">${['Comments','Discussions','To-do','Resolved'].map(f=>`<button data-filter="${f}" aria-pressed="${humanFilter===f}">${f}</button>`).join('')}</div><details class="human-settings"><summary>Collaboration settings</summary><label><input type="checkbox" data-human-setting="markers" ${humanSettings.markers?'checked':''}> Show comment markers</label><label><input type="checkbox" data-human-setting="previews" ${humanSettings.previews?'checked':''}> Show comment previews</label><label>Notifications<select data-human-setting="notifications">${['Mentions only','All activity','Off'].map(n=>`<option ${humanSettings.notifications===n?'selected':''}>${n}</option>`).join('')}</select></label><label><input type="checkbox" data-human-setting="resolved" ${humanSettings.resolved?'checked':''}> Show resolved comments</label><small>Local mock preferences; no notifications are sent.</small></details>${shown.map(card).join('')||'<p class="quiet-note">No items in this filter yet.</p>'}`;}
const markerLayer=document.createElement('div');markerLayer.className='comment-markers';markerLayer.setAttribute('aria-label','Passage comments');$('.document').appendChild(markerLayer);
function positionMarkers(){for(const b of markerLayer.children){const c=comments.find(c=>c.id===b.dataset.id),p=passage(c);if(p)b.style.top=(p.getBoundingClientRect().top-$('.document').getBoundingClientRect().top)+'px';}}
function refreshComments(){const a=$('#article');a.querySelectorAll('[data-human-preview]').forEach(n=>n.remove());a.querySelectorAll('.human-selected').forEach(n=>n.classList.remove('human-selected'));markerLayer.innerHTML='';if(focusWriting)return;for(const c of comments){const p=passage(c);if(!p||c.resolved&&!humanSettings.resolved)continue;if(humanSettings.markers){const b=document.createElement('button');b.className='comment-marker';b.dataset.human='preview';b.dataset.id=c.id;b.setAttribute('aria-label','Comment by '+c.author+' on '+c.anchor);b.setAttribute('aria-expanded',selectedComment===c.id||humanSettings.previews);b.textContent='▱';markerLayer.appendChild(b);}if(selectedComment===c.id){a.querySelectorAll('.claim.selected,[data-evidence].selected').forEach(n=>n.classList.remove('selected'));p.classList.add('human-selected');}if(selectedComment===c.id||humanSettings.previews){const preview=document.createElement('aside');preview.dataset.humanPreview=c.id;preview.contentEditable='false';preview.className='comment-preview';preview.innerHTML=`<button class="preview-close" data-human="close" data-id="${c.id}" aria-label="Close comment preview">×</button><div class="human-author"><strong>${esc(c.author)}</strong><small>${esc(c.role)} · Human comment</small></div><p>${esc(c.text)}</p>${humanActions(c,true)}${replyTarget===c.id?replyForm(c):''}`;p.after(preview);}}positionMarkers();}
function handleHuman(e){const b=e.target.closest('[data-human]');if(!b)return;e.preventDefault();e.stopPropagation();const c=comments.find(c=>c.id===b.dataset.id);if(!c)return;switch(b.dataset.human){case'preview':selectedComment=selectedComment===c.id?null:c.id;replyTarget=null;refreshComments();break;case'close':selectedComment=null;replyTarget=null;if(humanSettings.previews){humanSettings.previews=false;persistHuman();}refreshComments();break;case'reply':replyTarget=c.id;if(b.closest('[data-human-preview]')){selectedComment=c.id;refreshComments();}else renderHuman();break;case'cancel-reply':replyTarget=null;refreshComments();if(contextTab==='human')renderHuman();break;case'thread':selectedComment=c.id;humanFilter=c.resolved?'Resolved':c.type;setTab('human');openMobile();$('#thread-'+c.id)?.scrollIntoView({block:'nearest',behavior:'smooth'});break;case'passage':selectedComment=c.id;refreshComments();passage(c)?.scrollIntoView({block:'center',behavior:'smooth'});break;case'task':c.task=true;humanFilter='To-do';persistHuman();renderHuman();break;case'resolve':c.resolved=!c.resolved;selectedComment=null;persistHuman();refreshComments();renderHuman();break;}}
markerLayer.addEventListener('click',handleHuman);$('#article').addEventListener('click',e=>{if(e.target.closest('[data-human-preview]')){handleHuman(e);e.stopImmediatePropagation();}},true);$('#human-panel').addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){humanFilter=f.dataset.filter;replyTarget=null;renderHuman();}else handleHuman(e)});
function submitReply(e){const form=e.target.closest('[data-reply-form]');if(!form)return;e.preventDefault();e.stopPropagation();const c=comments.find(c=>c.id===form.dataset.replyForm),text=new FormData(form).get('reply').trim();if(!text)return;c.replies.push({author:'Jamie Laurent · Journalist',text});replyTarget=null;persistHuman();refreshComments();if(contextTab==='human')renderHuman();}
$('#article').addEventListener('submit',submitReply);$('#human-panel').addEventListener('submit',submitReply);
$('#human-panel').addEventListener('change',e=>{const key=e.target.dataset.humanSetting;if(!key)return;humanSettings[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;persistHuman();refreshComments();});
$('#focus-writing').onchange=e=>{focusWriting=e.target.checked;document.body.classList.toggle('focus-writing',focusWriting);if(focusWriting){selectedComment=null;replyTarget=null;}annotate();refreshComments();if(!focusWriting&&state!=='default')sync();};
// Ignore typing into local reply forms when saving/counting the article.
$('#article').addEventListener('input',e=>{if(e.target.closest('[data-human-preview]'))e.stopImmediatePropagation();},true);
$('#article').addEventListener('input',()=>requestAnimationFrame(positionMarkers));
new ResizeObserver(positionMarkers).observe($('.document'));window.addEventListener('resize',positionMarkers);
// Reuse the existing version dialogs and autosave rather than duplicating their behavior.
function sidebarHistory(){const milestones=versions.filter(v=>v.kind==='milestone');$('#named-versions').innerHTML=milestones.length?milestones.slice(0,4).map(v=>`<button data-milestone-id="${v.id}">${esc(v.name)}</button>`).join(''):'<small>No named versions yet</small>';}
const saveWithHistory=saveSnapshot;saveSnapshot=function(name){const result=saveWithHistory(name);sidebarHistory();return result;};
$('#named-versions').onclick=e=>{const b=e.target.closest('[data-milestone-id]');if(!b)return;historyPanel();$('#dialog-body').querySelector(`[data-version="${b.dataset.milestoneId}"]`)?.click();};
// Give the prototype a clearly identified previous mock milestone on first use.
if(!versions.some(v=>v.kind==='milestone')){versions.push({id:'mock-first-draft',name:'First complete draft',kind:'milestone',at:'2026-10-07T08:00:00+02:00',draft:snapshot()});save('authoria-versions',JSON.stringify(versions));}
count=function(){const doc=new DOMParser().parseFromString(snapshot().body,'text/html');$('#word-count').textContent=[...doc.body.children].map(n=>n.textContent).join(' ').trim().split(/\s+/).filter(Boolean).length+' words';};
const previousNoSource=noSource;noSource=function(){previousNoSource();setTab('ai');};
sidebarHistory();setTab('ai');groupEvidence();refreshComments();count();
